import{_ as a,C as t,o as n,c as i,E as o,a2 as d}from"./chunks/framework.IIAdu7fg.js";const c="/joinwell52/assets/completion-evidence-20261030/two-successes.figure.en.svg",b=JSON.parse(`{"title":"The report succeeded. The submit succeeded. Why is the task still open?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"The report succeeded. The submit succeeded. Why is the task still open?","date":"2026-10-30","published_date":"2026-10-30","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"Can two successful calls for different tasks settle the current task's session?","summary":"In a two-task control, A's report and B's submission both succeeded. A CodeFlowMu adapter settled A's session as done while the formal FCoP ledger still held A as active.","cover":"/assets/completion-evidence-20261030/two-successes.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Real FCoP 4 operations in temporary projects; private CodeFlowMu Google adapter module comparison; no live model or full UI","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-10-30-two-successes-one-task.md","filePath":"en/research/2026-10-30-two-successes-one-task.md","lastUpdated":null}`),l={name:"en/research/2026-10-30-two-successes-one-task.md"};function h(u,e,p,m,f,g){const s=t("ArticleCover"),r=t("ArticleTableScroll");return n(),i("div",null,[o(s,{image:"/assets/completion-evidence-20261030/two-successes.cover-v1.png",kicker:"Engineering research · Completion and evidence",title:"The report succeeded. The submit succeeded. Why is the task still open?",summary:"In a two-task control, A's report and B's submission both succeeded. A CodeFlowMu adapter settled A's session as done while the formal FCoP ledger still held A as active.",version:"2026-10-30",languageHref:"/zh/research/2026-10-30-two-successes-one-task",languageLabel:"中文"}),o(r,{language:"en"}),e[0]||(e[0]=d('<h1 id="the-report-succeeded-the-submit-succeeded-why-is-the-task-still-open" tabindex="-1">The report succeeded. The submit succeeded. Why is the task still open? <a class="header-anchor" href="#the-report-succeeded-the-submit-succeeded-why-is-the-task-still-open" aria-label="Permalink to &quot;The report succeeded. The submit succeeded. Why is the task still open?&quot;">​</a></h1><p>One worker has two assignments. They write the report for task A and successfully submit task B for review. If a runtime merely counts “report succeeded” and “submit succeeded,” it may conclude that <strong>A&#39;s work session is complete</strong>.</p><p>But A was never submitted. We tested exactly this distinction with two disposable tasks in our own system. One CodeFlowMu session-settlement path returned <code>done</code> for A, while FCoP, the formal task ledger, still recorded A as <code>active</code>. The adapter&#39;s <code>done</code> describes a <strong>session outcome</strong>, not FCoP&#39;s approved <code>done</code> lifecycle stage. Even with that distinction, the two layers disagree about whether this session handed off A.</p><h2 id="why-we-looked-at-our-own-completion-boundary" tabindex="-1">Why we looked at our own completion boundary <a class="header-anchor" href="#why-we-looked-at-our-own-completion-boundary" aria-label="Permalink to &quot;Why we looked at our own completion boundary&quot;">​</a></h2><p>We did not replay someone else&#39;s bug. <a href="https://github.com/paperclipai/paperclip/pull/18227" target="_blank" rel="noreferrer">Paperclip recently fixed a rejected completion report</a>: a provider ending normally must not replace a controller&#39;s rejection with a successful result. <a href="https://github.com/openai/codex/pull/58166" target="_blank" rel="noreferrer">Codex made recording completeness explicit</a>, independently of the task&#39;s terminal outcome. These changes address different products and different failures. Together, they prompted a useful question for us: <strong>which exact work item does each success prove?</strong></p><p>CodeFlowMu is our local multi-agent work system. It uses FCoP to keep formal tasks, reports, and lifecycle transitions. We asked whether its runtime could combine successful calls that belong to different tasks, and whether it could recover a formal report after process-local success flags disappear.</p><h2 id="two-green-checks-two-different-owners" tabindex="-1">Two green checks, two different owners <a class="header-anchor" href="#two-green-checks-two-different-owners" aria-label="Permalink to &quot;Two green checks, two different owners&quot;">​</a></h2><p>We pinned CodeFlowMu V3.0.129 and FCoP 4.0.5 source revisions and created two real FCoP tasks, A and B, in temporary directories. Both controls wrote A&#39;s formal report. The only changed step was the submission: one control submitted A, while the other submitted B. We passed the real operation results through the existing CodeFlowMu Google adapter modules and observed their early-stop and session-settlement decisions.</p><table tabindex="0"><thead><tr><th>What actually happened</th><th>Write A, submit A</th><th>Write A, submit B</th></tr></thead><tbody><tr><td>Formal report for A returned by FCoP</td><td>1</td><td>1</td></tr><tr><td>Adapter&#39;s “write succeeded / submit succeeded” flags</td><td>Yes / yes</td><td>Yes / yes</td></tr><tr><td>Adapter&#39;s session settlement for A</td><td><code>done</code></td><td><code>done</code></td></tr><tr><td>A&#39;s formal FCoP task stage</td><td><code>review</code></td><td><code>active</code></td></tr></tbody></table><figure><img src="'+c+'" alt="Controlled comparison: writing and submitting A moves A to review; writing A but submitting B leaves A active, although both session settlements say done."><figcaption>Controlled comparison. Read the session outcome and the formal task stage as separate facts.</figcaption></figure><p>Neither success was a fabricated string. The report write and task submission succeeded through real FCoP operations. <strong>The mistake lies in treating successes for separate tasks as one completion certificate.</strong> The tested runtime contract accumulates two booleans by tool name. Once both are true, it stops early and gives those flags priority during session settlement. The flags do not carry a common task ID or attempt ID, so they cannot establish that A was submitted.</p><h2 id="recovery-produces-the-opposite-error" tabindex="-1">Recovery produces the opposite error <a class="header-anchor" href="#recovery-produces-the-opposite-error" aria-label="Permalink to &quot;Recovery produces the opposite error&quot;">​</a></h2><p>We then removed the process-local success flags and asked the settlement module to rediscover A&#39;s report on disk. Both controls returned <code>blocked/no_valid_report</code>, even though FCoP&#39;s public query returned A&#39;s formal report in each case.</p><p>The mismatch is concrete. FCoP 4 stores reports as <code>REPORT-&lt;UUID&gt;.md</code> files and uses <code>subject_ref</code> to bind them to a task. The tested older finder first looks for a role suffix in the filename, then reads legacy relation fields. It does not use FCoP 4&#39;s formal report query. This creates two opposing blind spots in the same module path: <strong>broad in-memory success flags can settle A when it was not submitted; without those flags, a formally recorded report can appear absent.</strong></p><p>FCoP itself did not confuse the tasks. It kept A <code>active</code> in the cross-task control and moved A to <code>review</code> in the same-task control. The issue is in this runtime adapter&#39;s use of the ledger. Ten existing unit tests for the related modules passed, but none covered this cross-task and recovery comparison.</p><h2 id="what-should-count-as-a-handoff" tabindex="-1">What should count as a handoff? <a class="header-anchor" href="#what-should-count-as-a-handoff" aria-label="Permalink to &quot;What should count as a handoff?&quot;">​</a></h2><p>Our proposed rule is that a session completion claim should identify <strong>one task, one execution attempt, and one accepted report</strong>, consistent with the formal lifecycle stage. After a restart, the runtime should obtain the report head and task stage through FCoP&#39;s public queries. If process-local flags conflict with the ledger, it should retain an “unverified” outcome rather than declare completion or invent a missing report. This is a <strong>proposed contract, not an implemented feature</strong>.</p><p>The experiment called real FCoP operations and the current CodeFlowMu Google adapter modules. It did not run a live model, full UI, or production task. It does not establish a deployed incident or a finding in other providers. The <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-10-30-completion-evidence/00-report.en.md" target="_blank" rel="noreferrer">English evidence summary and public FCoP control script</a> state the method and limits; the private CodeFlowMu source is not in the public repository.</p><p>For engineers, the next question is where to enforce the binding: at each tool call, at settlement, or at both. For anyone who has seen an assistant say “done” while work remained open, the most useful detail is simpler: <strong>which layer said done, and where was the actual deliverable?</strong></p>',19))])}const k=a(l,[["render",h]]);export{b as __pageData,k as default};
